type HTTPServer = {
  host: string,
  port: i32,
  socket: i32,
  running: bool,
  requestCount: i32
}

func createHTTPServer(host: string, port: i32) -> HTTPServer {
  return {
    host: host,
    port: port,
    socket: 0,
    running: false,
    requestCount: 0
  }
}

// ──────────────────────────────────────────────────────────────────────────
