use "std/net"
use "std/http"

type Upstream = {
  id: string,
  host: string,
  port: i32,
  weight: i32,
  healthy: bool,
  requestCount: i32
}

type ProxyServer = {
  host: string,
  port: i32,
  socket: i32,
  running: bool,
  upstreams: [Upstream],
  totalRequests: i32
}

func main() -> void {
  println("")
  println("╔═══════════════════════════════════════════════════════╗")
  println("║  🔀 FreeLang 프록시 서버 (정식 모듈)                ║")
