// ──────────────────────────────────────────────────────────────────────────

func i32ToString(n: i32) -> string {
  if n == 0 {
    return "0"
  }

  let negative = n < 0
  let abs = if negative { -n } else { n }

  let result = ""
  let temp = abs
  while temp > 0 {
    let digit = temp % 10
    let char = if digit == 0 { "0" }
             else if digit == 1 { "1" }
             else if digit == 2 { "2" }
             else if digit == 3 { "3" }
             else if digit == 4 { "4" }
             else if digit == 5 { "5" }
             else if digit == 6 { "6" }
             else if digit == 7 { "7" }
             else if digit == 8 { "8" }
             else { "9" }
    result = char + result
    temp = temp / 10
  }

  if negative {
    return "-" + result
  }
  return result
}

func stringToI32(s: string) -> i32 {
  if s.isEmpty() {
    return 0
  }

  let result: i32 = 0
  let negative = s.startsWith("-")
  let start = if negative { 1 } else { 0 }

  for i in start..s.length() {
    let char = s[i]
    let digit = if char == "0" { 0 }
              else if char == "1" { 1 }
              else if char == "2" { 2 }
              else if char == "3" { 3 }
              else if char == "4" { 4 }
              else if char == "5" { 5 }
              else if char == "6" { 6 }
              else if char == "7" { 7 }
              else if char == "8" { 8 }
              else if char == "9" { 9 }
              else { 0 }
    result = result * 10 + digit
  }

  if negative {
    return -result
  }
  return result
}

