// ──────────────────────────────────────────────────────────────────────────

func i32ToString(n: i32) -> string {
  if n == 0 {
    return "0"
  }

  let negative = n < 0
  let abs = if negative { -n } else { n }

  let result = ""
  let temp = abs
  while temp > 0 {
    let digit = temp % 10
    let char = if digit == 0 { "0" }
             else if digit == 1 { "1" }
             else if digit == 2 { "2" }
             else if digit == 3 { "3" }
             else if digit == 4 { "4" }
             else if digit == 5 { "5" }
             else if digit == 6 { "6" }
             else if digit == 7 { "7" }
             else if digit == 8 { "8" }
             else { "9" }
    result = char + result
    temp = temp / 10
  }

  if negative {
    return "-" + result
  }
  return result
}

func stringToI32(s: string) -> i32 {
  if s.isEmpty() {
    return 0
  }

  let result: i32 = 0
  let negative = s.startsWith("-")
  let start = if negative { 1 } else { 0 }

  for i in start..s.length() {
    let char = s[i]
    let digit = if char == "0" { 0 }
              else if char == "1" { 1 }
              else if char == "2" { 2 }
              else if char == "3" { 3 }
              else if char == "4" { 4 }
              else if char == "5" { 5 }
              else if char == "6" { 6 }
              else if char == "7" { 7 }
              else if char == "8" { 8 }
              else if char == "9" { 9 }
              else { 0 }
    result = result * 10 + digit
  }

  if negative {
    return -result
  }
  return result
}

func boolToString(b: bool) -> string {
  if b {
    return "true"
  }
  return "false"
}

// ──────────────────────────────────────────────────────────────────────────
// 🔒 보안 검증 함수
// ──────────────────────────────────────────────────────────────────────────

func isValidBlogId(idStr: string) -> bool {
  // ID는 숫자만 허용, 길이 1-10자
  if idStr.isEmpty() || idStr.length() > 10 {
    return false
  }

  // 모든 문자가 숫자인지 확인
  for i in 0..idStr.length() {
    let char = idStr[i]
    if !isDigitChar(char) {
      return false
    }
  }

  return true
}

func isDigitChar(char: string) -> bool {
  // 문자가 숫자인지 확인
  if char == "0" || char == "1" || char == "2" || char == "3" || char == "4" {
    return true
  }
  if char == "5" || char == "6" || char == "7" || char == "8" || char == "9" {
    return true
  }
  return false
}

func isValidQueryParam(paramName: string, paramValue: string) -> bool {
  // 쿼리 파라미터 검증

  // 파라미터 이름 검증
  if paramName.isEmpty() || paramName.length() > 50 {
    return false
  }

  // 파라미터 값 검증
  if paramValue.isEmpty() || paramValue.length() > 256 {
    return false
  }

  // XSS 패턴 차단
  if paramValue.contains("<") || paramValue.contains(">") {
    return false
  }

  // SQL injection 패턴 차단
  if paramValue.contains("'") || paramValue.contains("\"") || paramValue.contains(";") {
    return false
  }

  return true
}

func isSecureQueryString(query: map[string]string) -> bool {
  // 전체 쿼리 문자열 검증

  for key in query {
    let value = query[key]
    if !isValidQueryParam(key, value) {
      return false
    }
  }

  return true
}

