// FreeLang 네트워킹 모듈
// std/net 기반 실제 TCP 소켓 통신 구현
// ============================================================================

use "std/net"

// ──────────────────────────────────────────────────────────────────────────
// 1. 소켓 관리
// ──────────────────────────────────────────────────────────────────────────

type ServerSocket = {
  fd: i32,              // 파일 디스크립터
  host: string,
  port: i32,
  backlog: i32,         // 대기 큐 크기
  isListening: bool
}

type ClientConnection = {
  fd: i32,              // 클라이언트 파일 디스크립터
  remoteHost: string,
  remotePort: i32,
  isConnected: bool,
  readBuffer: string,
  writeBuffer: string
}

func createServerSocket(host: string, port: i32, backlog: i32) -> ServerSocket {
  return {
    fd: 0,
    host: host,
    port: port,
    backlog: backlog,
    isListening: false
  }
}

// ──────────────────────────────────────────────────────────────────────────
// 2. 소켓 바인드 및 수신 대기
// ──────────────────────────────────────────────────────────────────────────

func bindSocket(socket: ServerSocket) -> bool {
  // std/net을 이용한 소켓 바인드
  // net.socket(AF_INET, SOCK_STREAM) → 파일 디스크립터
  // net.setsockopt(fd, SO_REUSEADDR, 1)
